/**
 * Utility for global styles isolation
 * Mainly applies "all: initial" css property to "root" selectors.
 * @param jssObj element style object
 * @param theme theme tokens
 * @return modified style object
 */
const isolateStyles = (jssObj: any, theme: any): any => {
  const { root, ...otherRules } = jssObj;
  return {
    root: (root && {
      all: "initial",
      fontFamily: theme.font.family.default,
      boxSizing: "border-box",
      ...root,
    }),
    ...otherRules,
  };
};

export default isolateStyles;
